"""EUD GPS trails for civil SAR (ПСС) HQ map — from stored Point history."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

from dateutil import parser as date_parser
from flask import Blueprint, jsonify, request
from flask_security import auth_required

from opentakserver.extensions import db
from opentakserver.functions import iso8601_string_from_datetime
from opentakserver.models.EUD import EUD
from opentakserver.models.Point import Point

track_api = Blueprint("track_api", __name__)

DEFAULT_MAX_POINTS = 2000
HARD_CAP_POINTS = 8000
DEFAULT_MIN_INTERVAL_S = 8


def _parse_dt(val):
    if not val:
        return None
    if isinstance(val, datetime):
        return val
    try:
        return date_parser.isoparse(str(val))
    except Exception:
        try:
            return datetime.fromisoformat(str(val).replace("Z", "+00:00"))
        except Exception:
            return None


def _as_naive_utc(dt: datetime | None) -> datetime | None:
    if dt is None:
        return None
    if dt.tzinfo is not None:
        return dt.astimezone(timezone.utc).replace(tzinfo=None)
    return dt


@track_api.route("/api/tracks", methods=["GET"])
@auth_required()
def list_tracks():
    """
    Downsampled GPS trails for HQ map.

    Query: since, until (ISO), uid, callsign, max_points, min_interval_s
    """
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    since = _as_naive_utc(_parse_dt(request.args.get("since"))) or (now - timedelta(hours=6))
    until = _as_naive_utc(_parse_dt(request.args.get("until"))) or now
    if until < since:
        since, until = until, since

    try:
        max_points = int(request.args.get("max_points") or DEFAULT_MAX_POINTS)
    except ValueError:
        max_points = DEFAULT_MAX_POINTS
    max_points = max(50, min(max_points, HARD_CAP_POINTS))

    try:
        min_interval_s = float(request.args.get("min_interval_s") or DEFAULT_MIN_INTERVAL_S)
    except ValueError:
        min_interval_s = DEFAULT_MIN_INTERVAL_S
    min_interval_s = max(0.0, min(min_interval_s, 300.0))

    uid = (request.args.get("uid") or "").strip() or None
    callsign = (request.args.get("callsign") or "").strip() or None

    q = (
        db.session.query(Point, EUD.callsign)
        .outerjoin(EUD, Point.device_uid == EUD.uid)
        .filter(
            Point.device_uid.isnot(None),
            Point.latitude.isnot(None),
            Point.longitude.isnot(None),
            Point.timestamp >= since,
            Point.timestamp <= until,
        )
        .order_by(Point.device_uid.asc(), Point.timestamp.asc())
    )
    if uid:
        q = q.filter(Point.device_uid == uid)
    if callsign:
        q = q.filter(EUD.callsign.ilike(callsign))

    # Cap raw rows fetched (before downsample) to avoid huge scans
    raw_cap = min(HARD_CAP_POINTS * 4, 40000)
    rows = q.limit(raw_cap).all()

    by_uid: dict[str, dict] = {}
    for pt, cs in rows:
        du = pt.device_uid
        if not du:
            continue
        bucket = by_uid.get(du)
        if bucket is None:
            bucket = {
                "device_uid": du,
                "callsign": cs or du,
                "points": [],
                "_last_ts": None,
            }
            by_uid[du] = bucket
        ts = pt.timestamp
        if ts and getattr(ts, "tzinfo", None):
            ts = ts.replace(tzinfo=None)
        last = bucket["_last_ts"]
        if last is not None and min_interval_s > 0 and ts is not None:
            delta = (ts - last).total_seconds()
            if delta < min_interval_s:
                continue
        bucket["points"].append(
            {
                "lat": pt.latitude,
                "lon": pt.longitude,
                "ts": iso8601_string_from_datetime(pt.timestamp) if pt.timestamp else None,
            }
        )
        bucket["_last_ts"] = ts

    # Global budget: trim longest trails if over max_points
    total = sum(len(b["points"]) for b in by_uid.values())
    if total > max_points and by_uid:
        # Keep roughly even spacing per trail
        for bucket in by_uid.values():
            pts = bucket["points"]
            if len(pts) <= 2:
                continue
            keep = max(2, int(len(pts) * max_points / total))
            if keep >= len(pts):
                continue
            step = len(pts) / keep
            sampled = [pts[int(i * step)] for i in range(keep - 1)]
            sampled.append(pts[-1])
            bucket["points"] = sampled

    results = []
    for bucket in by_uid.values():
        if len(bucket["points"]) < 2:
            continue
        results.append(
            {
                "device_uid": bucket["device_uid"],
                "callsign": bucket["callsign"],
                "points": bucket["points"],
            }
        )
    results.sort(key=lambda r: (r["callsign"] or "").lower())

    return jsonify(
        {
            "success": True,
            "since": iso8601_string_from_datetime(since),
            "until": iso8601_string_from_datetime(until),
            "results": results,
        }
    )
